package com.bechir.system;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;import android.text.*;import java.util.*;
public class MainActivity extends Activity {
 LinearLayout root,header,grid,dock; EditText search; TextView toggle; ScrollView scroll; boolean drawer; float down; android.content.SharedPreferences prefs; ArrayList<App> apps=new ArrayList<>();
 class App {String name,key; ResolveInfo info; Drawable icon; App(ResolveInfo r){info=r;name=r.loadLabel(getPackageManager()).toString();key=r.activityInfo.packageName;icon=r.loadIcon(getPackageManager());}}
 int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
 GradientDrawable glass(int c,int radius){GradientDrawable d=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{c,0x33242e50});d.setCornerRadius(dp(radius));d.setStroke(dp(1),0x407fa8ed);return d;}
 TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setGravity(Gravity.CENTER);return t;}
 LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
 void load(){apps.clear();PackageManager pm=getPackageManager();for(ResolveInfo r:pm.queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER),0))if(!r.activityInfo.packageName.equals(getPackageName()))apps.add(new App(r));apps.sort((a,b)->a.name.compareToIgnoreCase(b.name));}
 public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("launcher",0);getWindow().setStatusBarColor(0xff080d20);getWindow().setNavigationBarColor(0xff080d20);root=column();root.setPadding(dp(14),dp(8),dp(14),dp(8));root.setBackground(new Aurora());setContentView(root);root.setFocusableInTouchMode(true);
 header=column();root.addView(header);LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);header.addView(top);TextView brand=text("BECHIR  /  ULTRA",15,0xffb8d9ff);brand.setLetterSpacing(.16f);brand.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);top.addView(brand,new LinearLayout.LayoutParams(0,dp(42),1));TextView settings=text("⚙",25,Color.WHITE);settings.setBackground(glass(0x663d5580,16));top.addView(settings,new LinearLayout.LayoutParams(dp(44),dp(42)));settings.setOnClickListener(v->settings());
 LinearLayout hero=column();hero.setGravity(Gravity.CENTER);hero.setBackground(glass(0x55364d85,32));LinearLayout.LayoutParams h=new LinearLayout.LayoutParams(-1,dp(146));h.setMargins(0,dp(10),0,dp(12));header.addView(hero,h);TextClock clock=new TextClock(this);clock.setFormat24Hour("HH:mm");clock.setFormat12Hour("HH:mm");clock.setTextSize(66);clock.setTypeface(Typeface.create("sans-serif-light",0));clock.setTextColor(Color.WHITE);clock.setGravity(17);hero.addView(clock);TextClock date=new TextClock(this);date.setFormat24Hour("dd • MM • yyyy");date.setFormat12Hour("dd • MM • yyyy");date.setTextColor(0xffb5d7ff);date.setGravity(17);hero.addView(date);TextView section=text("مساحتي   /   MY SPACE",13,0xffc4d7f7);section.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);header.addView(section,new LinearLayout.LayoutParams(-1,dp(28)));
 search=new EditText(this);search.setSingleLine();search.setHint("ابحث عن تطبيق");search.setTextColor(Color.WHITE);search.setHintTextColor(0xffb8c6df);search.setPadding(dp(16),0,dp(16),0);search.setBackground(glass(0x77465b8c,22));root.addView(search,new LinearLayout.LayoutParams(-1,dp(54)));search.setVisibility(View.GONE);
 scroll=new ScrollView(this);scroll.setFillViewport(false);scroll.setVerticalScrollBarEnabled(false);grid=column();scroll.addView(grid);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
 dock=new LinearLayout(this);dock.setGravity(17);dock.setBackground(glass(0x99435a91,28));root.addView(dock,new LinearLayout.LayoutParams(-1,dp(76)));String[] names={"الهاتف","الرسائل","الكاميرا","المتصفح"};String[] symbols={"☎","✉","◉","◎"};for(int j=0;j<4;j++){final int k=j;LinearLayout cell=column();cell.setGravity(17);dock.addView(cell,new LinearLayout.LayoutParams(0,-1,1));cell.addView(text(symbols[j],30,0xffd7eaff));cell.addView(text(names[j],11,Color.WHITE));cell.setOnClickListener(v->shortcut(k));}
 toggle=text("⌃   مكتبة التطبيقات",15,0xffd5e7ff);root.addView(toggle,new LinearLayout.LayoutParams(-1,dp(42)));toggle.setOnClickListener(v->page(!drawer));search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){render();}public void afterTextChanged(Editable e){}});load();render();}
 void shortcut(int k){try{Intent i=k==0?new Intent(Intent.ACTION_DIAL):k==1?new Intent(Intent.ACTION_SENDTO,android.net.Uri.parse("smsto:")):k==2?new Intent(android.provider.MediaStore.INTENT_ACTION_STILL_IMAGE_CAMERA):new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("https://www.google.com"));startActivity(i);}catch(Exception e){Toast.makeText(this,"التطبيق غير متوفر",0).show();}}
 void settings(){new AlertDialog.Builder(this).setTitle("BECHIR ULTRA").setItems(new String[]{"تعيين الواجهة الرئيسية","خلفية الشفق","خلفية الليل","اختيار التطبيقات المفضلة"},(d,n)->{if(n==0){try{startActivity(new Intent(android.provider.Settings.ACTION_HOME_SETTINGS));}catch(Exception e){}}else if(n==3)page(true);else{prefs.edit().putBoolean("black",n==2).apply();root.invalidate();}}).show();}
 void launch(App a){try{startActivity(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER).setClassName(a.info.activityInfo.packageName,a.info.activityInfo.name).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}catch(Exception e){Toast.makeText(this,"تعذر فتح التطبيق",0).show();}}
 void tile(LinearLayout row,App a,int weight,int height,int iconSize,int tint){LinearLayout t=column();t.setGravity(17);t.setBackground(glass(tint,26));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(height),weight);p.setMargins(dp(4),dp(4),dp(4),dp(4));row.addView(t,p);ImageView icon=new ImageView(this);icon.setImageDrawable(a.icon);t.addView(icon,new LinearLayout.LayoutParams(dp(iconSize),dp(iconSize)));TextView name=text(a.name,14,Color.WHITE);name.setMaxLines(1);name.setEllipsize(android.text.TextUtils.TruncateAt.END);name.setPadding(dp(5),dp(7),dp(5),0);t.addView(name,new LinearLayout.LayoutParams(-1,-2));t.setOnClickListener(v->{v.animate().scaleX(.94f).scaleY(.94f).setDuration(75).withEndAction(()->{v.setScaleX(1);v.setScaleY(1);launch(a);}).start();});t.setOnLongClickListener(v->{String key="fav:"+a.key;boolean old=prefs.getBoolean(key,false);prefs.edit().putBoolean(key,!old).putBoolean("custom",true).apply();Toast.makeText(this,old?"أزيل من المفضلة":"أضيف إلى المفضلة",0).show();if(!drawer)render();return true;});}
 void render(){grid.removeAllViews();ArrayList<App> list=new ArrayList<>();String q=search.getText().toString().toLowerCase(Locale.ROOT);for(App a:apps)if(drawer?a.name.toLowerCase(Locale.ROOT).contains(q):prefs.getBoolean("fav:"+a.key,false))list.add(a);if(!drawer&&list.isEmpty()&&!prefs.getBoolean("custom",false)){for(App a:apps)if(a.key.contains("tiktok")||a.key.contains("zhiliao")||a.key.contains("whatsapp")||a.key.contains("camera")||a.key.contains("chrome"))list.add(a);for(App a:apps)if(list.size()<6&&!list.contains(a))list.add(a);}int i=0;while(i<list.size()){LinearLayout row=new LinearLayout(this);grid.addView(row);int count=drawer?3:2;int height=drawer?112:(i%4==0?142:116);for(int j=0;j<count;j++){if(i<list.size()){int weight=drawer?1:(j==0?3:2);tile(row,list.get(i++),weight,height,drawer?60:78,j==0?0x665177bd:0x665e479c);}else row.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));}}}
 void page(boolean value){drawer=value;header.setVisibility(value?View.GONE:View.VISIBLE);dock.setVisibility(value?View.GONE:View.VISIBLE);search.setVisibility(value?View.VISIBLE:View.GONE);toggle.setText(value?"⌄   الشاشة الرئيسية":"⌃   مكتبة التطبيقات");if(!value){search.setText("");((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(search.getWindowToken(),0);root.requestFocus();}render();scroll.scrollTo(0,0);}
 protected void onResume(){super.onResume();if(grid!=null){load();render();}}
 @Override public boolean dispatchTouchEvent(MotionEvent e){if(e.getAction()==0)down=e.getY();if(e.getAction()==1&&!drawer&&down-e.getY()>dp(100)){MotionEvent cancel=MotionEvent.obtain(e);cancel.setAction(MotionEvent.ACTION_CANCEL);super.dispatchTouchEvent(cancel);cancel.recycle();page(true);return true;}return super.dispatchTouchEvent(e);}
 @Override public void onBackPressed(){if(drawer)page(false);}
 @Override protected void onNewIntent(Intent i){super.onNewIntent(i);page(false);}
 class Aurora extends Drawable{Paint p=new Paint(3);public void draw(Canvas c){Rect b=getBounds();float w=b.width(),h=b.height();if(w<=0||h<=0)return;c.drawColor(0xff080d20);if(prefs.getBoolean("black",false))return;p.setShader(new RadialGradient(w*.88f,h*.12f,w*.95f,new int[]{0xff3b528e,0xff17284c,0x00080d20},null,Shader.TileMode.CLAMP));c.drawRect(b,p);p.setShader(new RadialGradient(w*.08f,h*.68f,w*.9f,new int[]{0xff4a286c,0xff201c49,0x00080d20},null,Shader.TileMode.CLAMP));c.drawRect(b,p);p.setShader(null);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(1));p.setColor(0x227db9ff);for(int j=0;j<5;j++)c.drawOval(w*.25f-j*dp(15),-h*.22f-j*dp(12),w*1.45f+j*dp(15),h*.48f+j*dp(12),p);p.setStyle(Paint.Style.FILL);}public void setAlpha(int a){}public void setColorFilter(ColorFilter f){}public int getOpacity(){return PixelFormat.OPAQUE;}}
}